package vn.uteb;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.security.authentication.TestingAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static vn.uteb.Domain.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:business;MODE=MSSQLServer;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","uteb.seed=false","uteb.mail.enabled=false"})
@ActiveProfiles("demo") @AutoConfigureMockMvc @Transactional
class BusinessConfigurationTest {
 @PersistenceContext EntityManager em;@Autowired ShopService shop;@Autowired BusinessSettings rules;@Autowired MockMvc mvc;@Autowired LoginThrottle limiter;
 Store store;Account admin,buyer,manager;Product product;
 Account account(String role){Account a=new Account();a.email=UUID.randomUUID()+"@test.local";a.name="Kiểm thử";a.roles=role;a.verified=true;a.storeId=role.equals("MANAGER")?store.id:null;a.passwordHash=shop.hashPassword("Test@12345");em.persist(a);return a;}
 void actor(Account a){SecurityContextHolder.getContext().setAuthentication(new TestingAuthenticationToken(a.email,"",a.roles));}
 Setting setting(String key){return em.createQuery("from Setting where name=:n",Setting.class).setParameter("n",key).getSingleResult();}
 void configure(String key,String value){actor(admin);Setting s=setting(key);shop.adminSave("settings",Map.of("id",s.id,"name",key,"settingValue",value));}
 Map<String,Object> checkout(){return Map.of("checkoutKey",UUID.randomUUID().toString(),"type","PICKUP","paymentMethod","COD","contactName","Khách hàng","phone","0901234567","scheduledAt","ASAP");}
 @BeforeEach void setup(){limiter.clear();store=new Store();store.name="Cửa hàng kiểm thử";store.address="123 Đường kiểm thử";store.phone="0901234567";em.persist(store);admin=account("ADMIN");buyer=account("CUSTOMER");manager=account("MANAGER");product=new Product();product.name="Món kiểm thử";product.category="Burrito";product.customizable=false;product.price=new BigDecimal("60000");product.storeId=store.id;em.persist(product);}
 @AfterEach void cleanup(){limiter.clear();SecurityContextHolder.clearContext();}
 @Test void changingFreeShippingThresholdChangesTheNextPreview(){actor(buyer);shop.cart(Map.of("productId",product.id,"quantity",3));Map<String,Object> body=new HashMap<>(checkout());body.put("type","DELIVERY");assertThat((BigDecimal)shop.preview(body).get("deliveryFee")).isZero();configure("free_shipping_threshold","200000");actor(buyer);assertThat((BigDecimal)shop.preview(body).get("deliveryFee")).isEqualByComparingTo("15000");}
 @Test void orderKeepsPointsPolicyAndRefundReversesOriginalEarnedPoints(){actor(buyer);shop.cart(Map.of("productId",product.id,"quantity",1));MealOrder old=shop.checkout(checkout()).getFirst();assertThat(old.pointsUnit).isEqualByComparingTo("1000");configure("points_unit","2000");actor(admin);for(String next:List.of("CONFIRMED","PREPARING","READY","COMPLETED"))shop.status(old.id,Map.of("status",next,"codCollected",true));assertThat(old.pointsEarned).isEqualTo(60);assertThat(buyer.points).isEqualTo(60);actor(buyer);RefundRequest refund=shop.refund(old.id,Map.of("reason","Món được giao không đúng yêu cầu đã đặt."));actor(admin);shop.refundDecision(refund.id,Map.of("status","APPROVED"));shop.refundDecision(refund.id,Map.of("status","REFUNDED","evidence","BANK-REFUND-123"));assertThat(buyer.points).isZero();actor(buyer);shop.cart(Map.of("productId",product.id,"quantity",1));assertThat(shop.checkout(checkout()).getFirst().pointsUnit).isEqualByComparingTo("2000");}
 @Test void newPaymentWindowDoesNotChangeExistingDeadline(){actor(buyer);shop.cart(Map.of("productId",product.id,"quantity",1));MealOrder old=shop.checkout(checkout()).getFirst();LocalDateTime deadline=old.paymentExpires;configure("payment_expiry_minutes","45");actor(buyer);shop.cart(Map.of("productId",product.id,"quantity",1));MealOrder next=shop.checkout(checkout()).getFirst();assertThat(next.paymentExpires).isAfter(LocalDateTime.now().plusMinutes(44));assertThat(old.paymentExpires).isEqualTo(deadline);}
 @ParameterizedTest @ValueSource(strings={"-1","0.5","NaN","100000001"}) void invalidThresholdIsRejected(String value){actor(admin);assertThatThrownBy(()->shop.adminSave("settings",Map.of("id",setting("free_shipping_threshold").id,"name","free_shipping_threshold","settingValue",value))).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
 @Test void credentialsAndRenamedKeysCannotBecomePublicSettings(){actor(admin);assertThatThrownBy(()->shop.adminSave("settings",Map.of("name","JWT_SECRET","settingValue","never expose"))).hasMessageContaining("không được hỗ trợ");assertThatThrownBy(()->shop.adminSave("settings",Map.of("id",setting("brand").id,"name","points_unit","settingValue","2000"))).hasMessageContaining("Không đổi mã");}
 @ParameterizedTest @ValueSource(strings={"settings","reward-offers","catering-packages"}) void nonAdminsCannotEditGlobalBusinessRules(String resource)throws Exception{for(Account a:List.of(buyer,manager))mvc.perform(post("/api/admin/"+resource).with(user(a.email).roles(a.roles)).contentType("application/json").content("{\"name\":\"brand\",\"settingValue\":\"forged\"}")).andExpect(status().isForbidden());}
 @Test void rewardCatalogChangesApplyToNewRedemptionsOnly(){RewardOffer offer=shop.all(RewardOffer.class).stream().filter(r->r.code.equals("DRINK")).findFirst().orElseThrow();buyer.points=2000;actor(buyer);Voucher old=shop.redeem("DRINK");offer.amount=new BigDecimal("30000");offer.points=600;Voucher next=shop.redeem("DRINK");assertThat(old.value).isEqualByComparingTo("25000");assertThat(next.value).isEqualByComparingTo("30000");assertThat(buyer.points).isEqualTo(900);offer.active=false;assertThatThrownBy(()->shop.redeem("DRINK")).hasMessageContaining("ngừng");}
 @Test void cateringUsesPackageLimitsAndKeepsOldQuote(){CateringPackage pack=shop.all(CateringPackage.class).getFirst();actor(buyer);Map<String,Object> body=new HashMap<>(Map.of("storeId",store.id,"packageId",pack.id,"people",10,"eventAt",LocalDateTime.now().plusDays(3).toString(),"contactName","Khách hàng","phone","0901234567","address","123 Đường tổ chức"));CateringRequest old=shop.catering(body);BigDecimal quote=old.quotedTotal;pack.pricePerPerson=new BigDecimal("120000");assertThat(shop.catering(body).quotedTotal).isEqualByComparingTo("1200000");assertThat(old.quotedTotal).isEqualByComparingTo(quote);pack.maxPeople=5;assertThatThrownBy(()->shop.catering(body)).hasMessageContaining("people");}
 @Test void renamingMenuDoesNotChangeRequiredGroupsIncludedPriceOrCalories(){Ingredient protein=new Ingredient();protein.name="Nhân có phụ thu";protein.groupName="PROTEIN";protein.price=new BigDecimal("15000");protein.calories=100;em.persist(protein);Ingredient sauce=new Ingredient();sauce.name="Sốt";sauce.groupName="SAUCE";sauce.calories=20;em.persist(sauce);product.customizable=true;product.requiredGroups="PROTEIN,SAUCE";product.includedProteinId=protein.id;product.ingredientCalorieFactor=new BigDecimal("0.5");String ids=protein.id+","+sauce.id;var before=shop.quote(product,ids);product.name="Tên món hoàn toàn khác";product.category="Tên danh mục mới";protein.name="Tên nhân mới";var after=shop.quote(product,ids);assertThat(after.price()).isEqualByComparingTo(before.price());assertThat(after.calories()).isEqualTo(before.calories()).isEqualTo(60);assertThat(ShopService.menuRequiredGroups(product)).containsExactly("PROTEIN","SAUCE");}
 @ParameterizedTest @ValueSource(strings={"4294967297","-4294967295","9223372036854775807","0","51"}) void oversizedQuantityCannotWrapIntoValidInteger(String quantity){actor(buyer);assertThatThrownBy(()->shop.cart(Map.of("productId",product.id,"quantity",quantity))).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThat(shop.where(CartLine.class,"userId",buyer.id)).isEmpty();}
 @Test void loginEndpointEnforcesBudget()throws Exception{for(int i=0;i<5;i++)mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"email\":\""+buyer.email+"\",\"password\":\"wrong\"}")).andExpect(status().isBadRequest());mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"email\":\""+buyer.email+"\",\"password\":\"Test@12345\"}")).andExpect(status().isTooManyRequests());}
 @ParameterizedTest @ValueSource(strings={"--------","++++++++","()()()()","1234567","1234567890123456"}) void shopApplicationRequiresActualPhoneDigits(String phone){actor(buyer);assertThatThrownBy(()->shop.shopApplication(Map.of("name","Cửa hàng mới","address","123 Đường thử nghiệm","phone",phone))).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThat(shop.where(ShopApplication.class,"userId",buyer.id)).isEmpty();}
}
